fn parse_relative_path(value: &str, allow_empty: bool) -> Result<PathBuf, WorkspaceError> {
    if value.as_bytes().contains(&0)
        || (!allow_empty && value.is_empty())
        || value.starts_with('/')
        || value.starts_with('\\')
        || looks_like_windows_prefix(value)
    {
        return Err(WorkspaceError::InvalidRelativePath {
            path: value.to_owned(),
        });
    }
    // Parse both separators explicitly so Windows traversal is rejected even
    // when this process is running on a Unix host.
    let mut path = PathBuf::new();
    let mut has_normal = false;
    for component in value.split(['/', '\\']) {
        match component {
            "" | "." => {}
            ".." => {
                return Err(WorkspaceError::InvalidRelativePath {
                    path: value.to_owned(),
                });
            }
            normal => {
                has_normal = true;
                path.push(normal);
            }
        }
    }
    if !allow_empty && !has_normal {
        return Err(WorkspaceError::InvalidRelativePath {
            path: value.to_owned(),
        });
    }
    Ok(path)
}

fn resolve_existing(
    &self,
    relative: &str,
    allow_root: bool,
) -> Result<PathBuf, WorkspaceError> {
    let relative_path = parse_relative_path(relative, allow_root)?;
    self.ensure_not_git(relative_path.as_path())?;
    let candidate = self.root.join(&relative_path);
    match fs::symlink_metadata(&candidate) {
        Ok(_) => {}
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            return Err(WorkspaceError::PathMissing {
                path: relative.to_owned(),
            });
        }
        Err(source) => {
            return Err(io_error(
                "reading workspace path metadata",
                &candidate,
                source,
            ))
        }
    }
    let canonical = fs::canonicalize(&candidate)
        .map_err(|source| io_error("canonicalizing workspace path", &candidate, source))?;
    self.ensure_inside(&canonical)?;
    self.ensure_not_git(canonical.strip_prefix(&self.root).unwrap_or(&canonical))?;
    Ok(canonical)
}

pub(crate) async fn run_check(&self, check_id: &str) -> Result<CommandResult, WorkspaceError> {
    validate_check_id(check_id)?;
    let config = self.load_config()?;
    let definition = config
        .checks
        .get(check_id)
        .cloned()
        .ok_or_else(|| WorkspaceError::UnknownCheck(check_id.to_owned()))?;
    let info = self.check_info(check_id.to_owned(), definition.clone())?;
    self.run_command(&info.program, &definition.args, info.timeout())
        .await
}
